void HAL_UART_IRQHandler(UART_HandleTypeDef *huart)
{
  /* Simplified UART interrupt handler for emulation */
  /* In emulation, we don't have real hardware interrupts */
  /* This function should do minimal work to avoid loops */

  /* Safety check */
  if (huart == NULL)
  {
    return;
  }

  /* In emulation, we simulate the most common interrupt scenarios */
  /* based on the current UART state */

  /* 1. Handle transmission if in BUSY_TX state */
  if (huart->gState == HAL_UART_STATE_BUSY_TX)
  {
    /* For interrupt mode transmission, we need to send data */
    /* We'll simulate sending all data at once */
    if (huart->TxXferCount > 0 && huart->pTxBuffPtr != NULL)
    {
      /* Calculate bytes to send based on word length */
      size_t bytes_per_element;
      if ((huart->Init.WordLength == UART_WORDLENGTH_9B) && (huart->Init.Parity == UART_PARITY_NONE))
      {
        bytes_per_element = 2; /* 9-bit data treated as 16-bit */
      }
      else
      {
        bytes_per_element = 1; /* 8-bit data */
      }

      /* Send all remaining data */
      size_t total_bytes = huart->TxXferCount * bytes_per_element;
      HAL_BE_Out(total_bytes);

      /* Update state */
      huart->TxXferCount = 0;
      huart->gState = HAL_UART_STATE_READY;

      /* Call transmit complete callback */
#if (USE_HAL_UART_REGISTER_CALLBACKS == 1)
      if (huart->TxCpltCallback != NULL)
      {
        huart->TxCpltCallback(huart);
      }
#else
      HAL_UART_TxCpltCallback(huart);
#endif /* USE_HAL_UART_REGISTER_CALLBACKS */
    }
    return;
  }

  /* 2. Handle reception if in BUSY_RX state */
  if (huart->RxState == HAL_UART_STATE_BUSY_RX)
  {
    /* For interrupt mode reception, we simulate receiving data */
    if (huart->RxXferCount > 0 && huart->pRxBuffPtr != NULL)
    {
      /* Try to read one element at a time */
      int bytes_read = HAL_BE_In(huart->pRxBuffPtr, 1);
      if (bytes_read > 0)
      {
        /* Update buffer pointer and count */
        if ((huart->Init.WordLength == UART_WORDLENGTH_9B) && (huart->Init.Parity == UART_PARITY_NONE))
        {
          huart->pRxBuffPtr += 2; /* 9-bit data */
        }
        else
        {
          huart->pRxBuffPtr += 1; /* 8-bit data */
        }
        huart->RxXferCount--;

        /* Check if reception is complete */
        if (huart->RxXferCount == 0)
        {
          huart->RxState = HAL_UART_STATE_READY;

          /* Call appropriate callback based on reception type */
          if (huart->ReceptionType == HAL_UART_RECEPTION_TOIDLE)
          {
            huart->ReceptionType = HAL_UART_RECEPTION_STANDARD;
#if (USE_HAL_UART_REGISTER_CALLBACKS == 1)
            if (huart->RxEventCallback != NULL)
            {
              huart->RxEventCallback(huart, huart->RxXferSize);
            }
#else
            HAL_UARTEx_RxEventCallback(huart, huart->RxXferSize);
#endif /* USE_HAL_UART_REGISTER_CALLBACKS */
          }
          else
          {
#if (USE_HAL_UART_REGISTER_CALLBACKS == 1)
            if (huart->RxCpltCallback != NULL)
            {
              huart->RxCpltCallback(huart);
            }
#else
            HAL_UART_RxCpltCallback(huart);
#endif /* USE_HAL_UART_REGISTER_CALLBACKS */
          }
        }
      }
    }
    return;
  }

  /* 3. Handle errors */
  if (huart->ErrorCode != HAL_UART_ERROR_NONE)
  {
    /* Call error callback */
#if (USE_HAL_UART_REGISTER_CALLBACKS == 1)
    if (huart->ErrorCallback != NULL)
    {
      huart->ErrorCallback(huart);
    }
#else
    HAL_UART_ErrorCallback(huart);
#endif /* USE_HAL_UART_REGISTER_CALLBACKS */

    /* Clear error code */
    huart->ErrorCode = HAL_UART_ERROR_NONE;
    return;
  }

  /* Default: no interrupt to handle */
  /* This prevents any recursive or exceptional loops */
}

