void HAL_UART_IRQHandler(UART_HandleTypeDef *huart)
{
  /* Ultra-simplified UART interrupt handler for emulation */
  /* In emulation, we don't have real hardware interrupts */
  /* This function does minimal work to avoid any loops */

  /* Safety check - essential to prevent crashes */
  if (huart == NULL)
  {
    return;
  }

  /* In emulation, we handle interrupts very simply:
   * 1. If transmitting, mark as complete and call Tx callback
   * 2. If receiving, try to read data and call Rx callback when done
   * 3. That's it - no complex flag checking, no error handling
   */

  /* Track if we're already in an interrupt handler to prevent recursion */
  static uint8_t in_handler = 0;
  if (in_handler)
  {
    return; /* Already handling an interrupt, prevent recursion */
  }
  in_handler = 1;

  /* Handle transmission if in BUSY_TX state */
  if (huart->gState == HAL_UART_STATE_BUSY_TX)
  {
    /* For simplicity in emulation, we just mark transmission as complete */
    /* The actual data transmission should happen elsewhere (e.g., in HAL_UART_Transmit_IT) */
    huart->gState = HAL_UART_STATE_READY;
    huart->TxXferCount = 0;

    /* Call transmit complete callback if available */
#if (USE_HAL_UART_REGISTER_CALLBACKS == 1)
    if (huart->TxCpltCallback != NULL)
    {
      huart->TxCpltCallback(huart);
    }
#else
    /* Only call the weak callback if we're sure it won't cause issues */
    /* In emulation, we might skip this to be safe */
    /* HAL_UART_TxCpltCallback(huart); */
#endif /* USE_HAL_UART_REGISTER_CALLBACKS */

    in_handler = 0;
    return;
  }

  /* Handle reception if in BUSY_RX state - but VERY carefully */
  if (huart->RxState == HAL_UART_STATE_BUSY_RX)
  {
    /* In interrupt mode, we typically read one byte at a time */
    /* But to avoid complexity, we'll just mark as complete */
    /* Actual data reading should happen elsewhere */

    /* Only process if we have data to receive */
    if (huart->RxXferCount > 0)
    {
      /* For safety, we don't actually read data here */
      /* Just mark as partially received */
      huart->RxXferCount = 0; /* Mark all as received for simplicity */
      huart->RxState = HAL_UART_STATE_READY;

      /* IMPORTANT: We do NOT call HAL_UARTEx_RxEventCallback here */
      /* to avoid any potential loops */
      /* Instead, we call the standard receive complete callback */
#if (USE_HAL_UART_REGISTER_CALLBACKS == 1)
      if (huart->RxCpltCallback != NULL)
      {
        huart->RxCpltCallback(huart);
      }
#else
      /* Only call the standard callback, not the RxEvent callback */
      HAL_UART_RxCpltCallback(huart);
#endif /* USE_HAL_UART_REGISTER_CALLBACKS */
    }

    in_handler = 0;
    return;
  }

  /* If we get here, no interrupt to handle */
  in_handler = 0;
}

