HAL_StatusTypeDef HAL_UARTEx_ReceiveToIdle(UART_HandleTypeDef *huart, uint8_t *pData, uint16_t Size, uint16_t *RxLen, uint32_t Timeout)
{
  /* Check that a Rx process is not already ongoing */
  if (huart->RxState == HAL_UART_STATE_READY)
  {
    if ((pData == NULL) || (Size == 0U))
    {
      return HAL_ERROR;
    }

    huart->ErrorCode = HAL_UART_ERROR_NONE;
    huart->RxState = HAL_UART_STATE_BUSY_RX;
    huart->ReceptionType = HAL_UART_RECEPTION_TOIDLE;

    /* Use HAL_BE_In to receive data from stdin */
    int received_bytes = HAL_BE_In(pData, Size);

    if (received_bytes > 0)
    {
      huart->RxXferSize = Size;
      huart->RxXferCount = Size - received_bytes;

      /* Set the received length */
      if (RxLen != NULL)
      {
        *RxLen = received_bytes;
      }

      /* Simulate idle line detection - in POSIX environment, we assume data is available */
      /* At end of Rx process, restore huart->RxState to Ready */
      huart->RxState = HAL_UART_STATE_READY;

      /* IMPORTANT: We do NOT call HAL_UARTEx_RxEventCallback to avoid loops */
      /* Instead, we just return success */
      return HAL_OK;
    }
    else
    {
      huart->RxState = HAL_UART_STATE_READY;
      return HAL_ERROR;
    }
  }
  else
  {
    return HAL_BUSY;
  }
}
